import{_ as o,o as t,c as a,a2 as r}from"./chunks/framework.Bqn-bhhR.js";const g=JSON.parse('{"title":"Overview","description":"","frontmatter":{},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md","lastUpdated":1786047222000}'),n={name:"guide/introduction.md"};function i(s,e,d,l,c,h){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h1><p><strong>Codemark</strong> bookmarks code by structure, not by line number. A <code>file:line</code> reference breaks the moment you add a newline above it; Codemark uses <a href="https://tree-sitter.github.io/tree-sitter/" target="_blank" rel="noreferrer">tree-sitter</a> to remember <em>what</em> you marked — a function, a type, a block — and anchors the bookmark to that named structure so it still resolves after you refactor or reformat around it.</p><p>That durability is what makes it useful for long AI agent sessions, code audits, and keeping track of things you want to find again.</p><h2 id="why-codemark" tabindex="-1">Why Codemark? <a class="header-anchor" href="#why-codemark" aria-label="Permalink to &quot;Why Codemark?&quot;">​</a></h2><p>The way we navigate code hasn&#39;t caught up with how code is produced now.</p><ul><li><strong>Spending time in the editor matters less, but navigation still does.</strong> In the AI era, you read and direct more than you type by hand. What slows you down is <em>finding</em> the right spot — the entry point, the boundary, the place a previous session already understood. Quick, durable navigation is the bottleneck.</li><li><strong>Easy navigation.</strong> A keyboard-driven dashboard (lazygit-style, vim motions) lets you fly through bookmarks, collections, and search without leaving the terminal.</li><li><strong>Distill agent discoveries.</strong> When an agent explores a codebase and finds the load-bearing code, that knowledge evaporates at session end unless it&#39;s captured. Codemark turns those discoveries into durable, queryable bookmarks.</li><li><strong>Give agents high-level context.</strong> Instead of re-exploring from scratch each session, an agent loads a collection and instantly knows where the important code lives and why.</li><li><strong>Durable enough to survive refactors.</strong> Bookmarks are anchored to AST structure and a normalized content hash, so renaming a file, extracting a method, or reformatting doesn&#39;t lose your place.</li><li><strong>The encoding is semantic.</strong> A bookmark encodes &quot;the function named <code>validate_token</code>&quot; — a query that makes sense to a human. Vectors do not. You can read a bookmark&#39;s query and immediately understand what it points at.</li><li><strong>Sharable context.</strong> Collections are guided tours you can publish and pull across a team, so onboarding and institutional knowledge travel with the code.</li></ul><h2 id="vision" tabindex="-1">Vision <a class="header-anchor" href="#vision" aria-label="Permalink to &quot;Vision&quot;">​</a></h2><p>Code navigation should be <strong>structural, durable, and shareable</strong> — equally useful to a human reading a codebase and to an agent that needs to act on it. Codemark&#39;s goal is to be the durable memory layer over a codebase: the place where &quot;this is where the important thing lives, and this is why&quot; persists across sessions, refactors, and handoffs.</p><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><h3 id="search" tabindex="-1">Search <a class="header-anchor" href="#search" aria-label="Permalink to &quot;Search&quot;">​</a></h3><ul><li><strong>Semantic search.</strong> Find bookmarks by intent (&quot;where is authentication handled?&quot;) using local vector embeddings generated on-device with <a href="https://github.com/huggingface/candle" target="_blank" rel="noreferrer">candle</a> — no API key, no network call for inference.</li><li><strong>Full-text search.</strong> Substring matching across notes, context, tags, and file paths via SQL, so exact lookups stay fast and predictable.</li></ul><h3 id="bookmark-metadata" tabindex="-1">Bookmark metadata <a class="header-anchor" href="#bookmark-metadata" aria-label="Permalink to &quot;Bookmark metadata&quot;">​</a></h3><p>Every bookmark carries rich, append-only metadata:</p><ul><li><strong>Notes &amp; comments</strong> — two distinct channels. <em>Notes</em> are durable, plain-prose explanations of what the code is; <em>comments</em> are markdown discussion tied to a task, ticket, or PR.</li><li><strong>Tags</strong> — structured, colon-prefixed taxonomy (<code>feature:auth</code>, <code>layer:api</code>, <code>role:entrypoint</code>) for precise filtering.</li><li><strong>Links</strong> — attach PRs, issues, and docs to a collection.</li><li><strong>Health status</strong> — <code>active</code>, <code>drifted</code>, <code>stale</code>, or <code>archived</code>, computed by re-resolving the structural query against the current tree.</li><li><strong>Git context</strong> — commit hash, branch, and breadcrumbs up the enclosing structure.</li></ul><h3 id="the-dashboard-tui" tabindex="-1">The dashboard (TUI) <a class="header-anchor" href="#the-dashboard-tui" aria-label="Permalink to &quot;The dashboard (TUI)&quot;">​</a></h3><ul><li><strong>Keyboard-driven, lazygit-inspired.</strong> <code>1</code>–<code>5</code> jump to panes, <code>+</code>/<code>-</code> resize, <code>Ctrl+C</code> quits from anywhere.</li><li><strong>Vim motions.</strong> <code>j</code>/<code>k</code> move, <code>J</code>/<code>K</code> scroll, <code>h</code>/<code>l</code> step through a collection, <code>n</code>/<code>N</code> follow markdown links.</li><li><strong>Mouse support.</strong> Click to focus and select, scroll to navigate panes.</li><li><strong>Many themes.</strong> Bundled schemes including Catppuccin Mocha, Everforest, Dracula, Nord, Gruvbox, Solarized, and OneHalfDark. Drop in <code>.tmTheme</code> or base16 <code>.yaml</code> files for fully cohesive preview + chrome theming.</li></ul><h3 id="repositories" tabindex="-1">Repositories <a class="header-anchor" href="#repositories" aria-label="Permalink to &quot;Repositories&quot;">​</a></h3><ul><li><strong>Current repository detection.</strong> Walks up from your working directory to find the Git root and stores bookmarks alongside it — zero setup.</li><li><strong>Multi-repo queries.</strong> Query several repositories at once by identity (<code>--repo owner/name</code>) or by explicit database paths (<code>--db path</code>).</li></ul><h3 id="integration" tabindex="-1">Integration <a class="header-anchor" href="#integration" aria-label="Permalink to &quot;Integration&quot;">​</a></h3><ul><li><strong>Agent skill.</strong> An installable skill (<code>codemark install-skill</code>) teaches AI coding agents to create and recall bookmarks for you. Works with Claude Code, GitHub Copilot, Gemini CLI, and any agent that loads <code>.agents/skills</code>.</li><li><strong>Configurable editor.</strong> Press <code>o</code> to open a bookmark in your editor — per-extension commands, terminal vs GUI detection, and <code>$EDITOR</code> fallback.</li></ul>',20)])])}const m=o(n,[["render",i]]);export{g as __pageData,m as default};
